html[data-ui-system="manifest"] .lflScenarioMonthOption:has(input:focus-visible){outline:2px solid var(--ui-accent);outline-offset:2px;}


/* Conversation records use the same editorial hierarchy as other work logs. */
html[data-ui-system="manifest"] .lcwaiMsg.is-user .lcwaiMsgBody,
html[data-ui-system="manifest"] .lcwaiMsg.is-ai .lcwaiMsgBody {background:transparent !important;color:var(--ui-text) !important;padding:0;box-shadow:none !important;border:0 !important}
html[data-ui-system="manifest"] .lcwaiMsgWho {color:var(--ui-text-secondary) !important}
html[data-ui-system="manifest"] .lcwaiMsgMeta {color:var(--ui-text-secondary) !important}

/* Descendant text follows the selected control's foreground pair. */
html[data-ui-system="manifest"] .umStatusTab.isActive b {color:inherit !important}
html[data-ui-system="manifest"] .blGuideSidebar nav button[aria-pressed="true"] {color:var(--ui-selected-ink) !important}

html[data-ui-system="manifest"] .autoTemplateIcon {font:500 var(--ui-font-lg)/1.2 var(--ui-font-mono) !important;color:var(--ui-text-muted) !important}


/* Native range controls retain keyboard/value behavior with square handles. */
html[data-ui-system="manifest"] [data-ui-migrated] input[type="range"]{appearance:none;background:transparent!important;height:20px;cursor:pointer;}
html[data-ui-system="manifest"] [data-ui-migrated] input[type="range"]::-webkit-slider-runnable-track{height:4px;background:var(--ui-surface-strong);border:0;border-radius:var(--ui-radius);}
html[data-ui-system="manifest"] [data-ui-migrated] input[type="range"]::-webkit-slider-thumb{appearance:none;width:14px;height:14px;margin-top:-5px;background:var(--ui-accent);border:0;border-radius:var(--ui-radius);}
html[data-ui-system="manifest"] [data-ui-migrated] input[type="range"]::-moz-range-track{height:4px;background:var(--ui-surface-strong);border:0;border-radius:var(--ui-radius);}
html[data-ui-system="manifest"] [data-ui-migrated] input[type="range"]::-moz-range-thumb{width:14px;height:14px;background:var(--ui-accent);border:0;border-radius:var(--ui-radius);}
html[data-ui-system="manifest"] .lcwaiLayPreset.is-active .lcwaiLayThumb.is-text i{background:none!important;color:var(--ui-text-secondary)!important;}
